    /// ZIP method 8 (deflate) is what zlib unlocks beyond the gzip filter: without `HAVE_ZLIB_H`
    /// libarchive's ZIP reader lists deflated entries but cannot read their data. No filter is
    /// involved (`["none"]`) -- the decoding happens inside the format reader.
    #[test]
    fn deflated_zip_read_entry_returns_the_exact_original_bytes() {
        let file = open_fixture("sample-deflate.zip");
        assert_eq!(filter_names(file.as_raw_fd()).unwrap(), vec!["none"]);
        let file = open_fixture("sample-deflate.zip");
        let names: Vec<String> = entries(file.as_raw_fd())
            .unwrap()
            .into_iter()
            .map(|e| e.path)
            .collect();
        assert_eq!(names, vec!["hello.txt", "second.txt"]);
        let file = open_fixture("sample-deflate.zip");
        let data = read_entry(file.as_raw_fd(), "hello.txt").unwrap();
        assert_eq!(data, Some(b"hello world".to_vec()));
        let file = open_fixture("sample-deflate.zip");
        let data = read_entry(file.as_raw_fd(), "second.txt").unwrap();
        assert_eq!(data, Some(b"more data, a bit longer".to_vec()));
    }

    /// No format bids on the first header: `Unsupported`, the design's own variant for "not an
    /// archive we can open", rather than `Fatal` ("damaged") -- and never a panic.
    #[test]
    fn a_non_archive_is_unsupported_not_a_panic() {
        let dir = tempdir();
        let path = dir.path().join("not-an-archive");
        File::create(&path)
            .unwrap()
            .write_all(b"this is not an archive of any kind")
            .unwrap();
        let file = File::open(&path).unwrap();
        let result = entries(file.as_raw_fd());
        assert!(
            matches!(result, Err(ArchiveError::Unsupported(ref m)) if m.contains("Unrecognized")),
            "{result:?}"
        );
    }

    /// A tiny, dependency-free stand-in for a `tempfile`-style crate: this crate deliberately adds
    /// no dev-dependency for a handful of tests, matching the project's own "smallest working
    /// thing first" convention. A directory under `std::env::temp_dir()` named with the process
    /// id, an incrementing counter and the current time is unique enough for tests that never run
    /// the same process twice concurrently under the same name, and is removed on drop.
    pub(crate) struct TempDir(PathBuf);
    impl TempDir {
        pub(crate) fn path(&self) -> &Path {
            &self.0
        }
    }
    impl Drop for TempDir {
        fn drop(&mut self) {
            let _ = std::fs::remove_dir_all(&self.0);
        }
    }
    pub(crate) fn tempdir() -> TempDir {
        use std::sync::atomic::AtomicU32;
        use std::sync::atomic::Ordering;
        static COUNTER: AtomicU32 = AtomicU32::new(0);
        let n = COUNTER.fetch_add(1, Ordering::Relaxed);
        let nanos = std::time::SystemTime::now()
            .duration_since(std::time::UNIX_EPOCH)
            .unwrap()
            .as_nanos();
        let path = std::env::temp_dir().join(format!(
            "fylz-archive-test-{}-{}-{}",
            std::process::id(),
            n,
            nanos
        ));
        std::fs::create_dir_all(&path).unwrap();
        TempDir(path)
    }
